package com.dixitdada.journalApp.controller; import com.dixitdada.journalApp.entity.JournalEntry; import com.dixitdada.journalApp.service.JournalService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/journals") @RequiredArgsConstructor public class JournalEntryController { private final JournalService s; @GetMapping public List<JournalEntry> all(Authentication a){return s.list(a.getName());} @PostMapping public JournalEntry create(Authentication a,@Valid @RequestBody JournalEntry e){return s.create(a.getName(),e);} @GetMapping("/{id}") public JournalEntry one(Authentication a,@PathVariable String id){return s.one(a.getName(),id);} @PutMapping("/{id}") public JournalEntry update(Authentication a,@PathVariable String id,@Valid @RequestBody JournalEntry e){return s.update(a.getName(),id,e);} @DeleteMapping("/{id}") public void delete(Authentication a,@PathVariable String id){s.delete(a.getName(),id);} }